SELECT DISTINCT ?label ?qid
WHERE {
  ?algo wdt:P31 wd:Q127020 ;
        rdfs:label ?label .
  FILTER(LANG(?label) = "en")
  # algorithmic task: Sorting items under a total order
  wd:Q6825656 wdt:P1578 ?algo .
  BIND(STRAFTER(STR(?algo), STR(wd:)) AS ?qid)
}
LIMIT 10
